-- q3 badrate crudo vs estandarizado por mes abierto por entidad y bucket
WITH b AS (SELECT entidad AS ent, CASE WHEN flg_clean = 1 THEN '1_clean' ELSE '2_dirty' END AS bucket, CAST(codmes AS VARCHAR) AS cm, CAST(count(1) AS DOUBLE) AS n, CAST(sum(target_12m) AS DOUBLE) AS m FROM disc_model_owner.ds_adm_bpe_bankbn_cal WHERE flg_calib = 1 AND flg_clean IN (0, 1) GROUP BY 1, 2, 3), w AS (SELECT cm, sum(n) AS n_ref FROM b GROUP BY cm), j AS (SELECT b.ent, b.bucket, b.cm, b.n, b.m, b.m / b.n AS p_m, w.n_ref AS peso FROM b JOIN w ON w.cm = b.cm) SELECT ent, bucket, CAST(sum(n) AS BIGINT) AS n, CAST(sum(m) AS BIGINT) AS malos, count(DISTINCT cm) AS meses, CAST(min(n) AS BIGINT) AS n_min_mes, CAST(max(n) AS BIGINT) AS n_max_mes, CAST(sum(CASE WHEN m = 0 THEN 1 ELSE 0 END) AS BIGINT) AS meses_sin_malos, round(100e0 * sum(m) / sum(n), 2) AS badrate_crudo_pct, round(100e0 * sum(peso * p_m) / sum(peso), 2) AS badrate_estandarizado_pct, round(100e0 * (sum(peso * p_m) / sum(peso) - sum(m) / sum(n)), 2) AS efecto_composicion_pp, round(100e0 * sqrt(sum(peso * peso * p_m * (1e0 - p_m) / n)) / sum(peso), 3) AS se_estandarizado_pp, round(100e0 * sum(CASE WHEN cm <= '202312' THEN n ELSE 0e0 END) / sum(n), 1) AS pct_masa_2022_2023, round(100e0 * sum(CASE WHEN cm <= '202312' THEN m ELSE 0e0 END) / nullif(sum(CASE WHEN cm <= '202312' THEN n ELSE 0e0 END), 0e0), 2) AS badrate_2022_2023_pct, round(100e0 * sum(CASE WHEN cm > '202312' THEN m ELSE 0e0 END) / nullif(sum(CASE WHEN cm > '202312' THEN n ELSE 0e0 END), 0e0), 2) AS badrate_2024_2025_pct FROM j GROUP BY ent, bucket ORDER BY ent, bucket
